CREATE OR REPLACE FUNCTION get_loyalty_tier(p_spend NUMERIC)
RETURNS VARCHAR AS $$
DECLARE
    v_tier VARCHAR(20);
BEGIN
    IF p_spend >= 5000 THEN
        v_tier := 'PLATINUM';
    ELSIF p_spend >= 1000 THEN
        v_tier := 'GOLD';
    ELSE
        v_tier := 'STANDARD';
    END IF;

    RETURN v_tier;
END;
$$ LANGUAGE plpgsql IMMUTABLE;

DO $$
DECLARE
    rec        record;
    grand_total numeric := 0;
BEGIN
    FOR rec IN
        SELECT id, amount
        FROM orders
        WHERE status = 'PENDING'
        ORDER BY id
    LOOP
        grand_total := grand_total + rec.amount;

        IF rec.amount > 1000 THEN
            RAISE NOTICE 'Order % is high value (%');
        END IF;
    END LOOP;

    RAISE NOTICE 'Pending total: %', grand_total;
END $$;
